import styled from "styled-components";
import { sectionTitleGradient } from "../../theme/sectionStyles";
import GitHubIcon from "@mui/icons-material/GitHub";
import LinkedInIcon from "@mui/icons-material/LinkedIn";
import InstagramIcon from "@mui/icons-material/Instagram";
import ArticleIcon from "@mui/icons-material/Article";
import CodeIcon from "@mui/icons-material/Code";
import { Bio } from "../../data/constants";

const FooterContainer = styled.footer`
  width: 100%;
  padding: clamp(44px, 7vw, 72px) clamp(16px, 4vw, 32px) clamp(28px, 5vw, 44px);
  display: flex;
  justify-content: center;
  position: relative;
  z-index: 1;
  border-top: 1px solid ${({ theme }) => theme.navBorder};
  background: ${({ theme }) => theme.bg};
`;

const FooterWrapper = styled.div`
  width: 100%;
  max-width: min(1240px, 92vw);
  display: flex;
  flex-wrap: wrap;
  gap: 16px 32px;
  align-items: center;
  justify-content: space-between;
  padding: 0;
  color: ${({ theme }) => theme.text_primary};
`;

const Logo = styled.p`
  margin: 0;
  font-size: clamp(1.25rem, 2.6vw, 1.65rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.1;
  ${sectionTitleGradient}
`;

const SocialMediaIcons = styled.div`
  display: flex;
  justify-content: center;
  gap: 12px;
`;

const SocialMediaIcon = styled.a`
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: ${({ theme }) => theme.text_primary};
  text-decoration: none;
  width: 42px;
  height: 42px;
  border-radius: 12px;
  border: 1px solid ${({ theme }) => theme.navBorder};
  background: ${({ theme }) => theme.card_light};
  transition:
    transform 0.2s ease,
    border-color 0.2s ease;
  &:hover {
    transform: translateY(-2px);
    border-color: ${({ theme }) => theme.primary}66;
    color: ${({ theme }) => theme.primary};
  }
  svg {
    font-size: 1.2rem;
  }
`;

const Copyright = styled.p`
  margin: 2px 0 0;
  font-size: 0.85rem;
  flex-basis: 100%;
  color: ${({ theme }) => theme.text_muted};
  text-align: left;
`;

function Footer() {
  const year = new Date().getFullYear();

  return (
    <FooterContainer>
      <FooterWrapper>
        <Logo>{Bio.name}</Logo>
        <SocialMediaIcons>
          <SocialMediaIcon
            href={Bio.github}
            target="_blank"
            rel="noopener noreferrer"
            aria-label="GitHub"
          >
            <GitHubIcon />
          </SocialMediaIcon>
          <SocialMediaIcon
            href={Bio.linkedin}
            target="_blank"
            rel="noopener noreferrer"
            aria-label="LinkedIn"
          >
            <LinkedInIcon />
          </SocialMediaIcon>
          <SocialMediaIcon
            href={Bio.medium}
            target="_blank"
            rel="noopener noreferrer"
            aria-label="Medium"
          >
            <ArticleIcon />
          </SocialMediaIcon>
          <SocialMediaIcon
            href={Bio.codepen}
            target="_blank"
            rel="noopener noreferrer"
            aria-label="CodePen"
          >
            <CodeIcon />
          </SocialMediaIcon>
          <SocialMediaIcon
            href={Bio.insta}
            target="_blank"
            rel="noopener noreferrer"
            aria-label="Instagram"
          >
            <InstagramIcon />
          </SocialMediaIcon>
        </SocialMediaIcons>
        <Copyright>&copy; {year} {Bio.name}. All rights reserved.</Copyright>
      </FooterWrapper>
    </FooterContainer>
  );
}

export default Footer;
